1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root { --cell: 28px; }
9	  * { box-sizing: border-box; }
10	  body {
11	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
12	    background: #14161c; color: #e8e8ec; font: 15px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
13	  }
14	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; flex-wrap: wrap; justify-content: center; }
15	  .board {
16	    display: grid; grid-template-columns: repeat(10, var(--cell)); grid-template-rows: repeat(20, var(--cell));
17	    gap: 1px; padding: 1px; background: #262a33; border: 2px solid #3a3f4b; border-radius: 4px;
18	  }
19	  .cell { width: var(--cell); height: var(--cell); background: #0d0f14; }
20	  .cell[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18), inset 0 -3px 0 rgba(0,0,0,0.25); }
21	  .panel { display: flex; flex-direction: column; gap: 14px; min-width: 150px; }
22	  .stat { background: #1c1f27; border: 1px solid #2c313c; border-radius: 6px; padding: 8px 12px; }
23	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: #9097a6; }
24	  .stat .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
25	  .preview { display: grid; grid-template-columns: repeat(4, 20px); grid-template-rows: repeat(2, 20px); gap: 1px; margin-top: 6px; }
26	  .preview .mini { width: 20px; height: 20px; background: transparent; }
27	  .preview .mini[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18); }
28	  .status { min-height: 1.4em; color: #ff8a80; font-weight: 600; }
29	  .help { font-size: 13px; color: #9097a6; }
30	  .help kbd { background: #2c313c; border-radius: 3px; padding: 0 5px; color: #e8e8ec; font: inherit; }
31	  button {
32	    background: #3a6ff7; color: #fff; border: 0; border-radius: 6px; padding: 8px 12px;
33	    font: inherit; font-weight: 600; cursor: pointer;
34	  }
35	</style>
36	</head>
37	<body>
38	<div class="game">
39	  <div class="board" data-testid="board"></div>
40	  <div class="panel">
41	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score">0</div></div>
42	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level">1</div></div>
43	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines">0</div></div>
44	    <div class="stat"><div class="label">Next</div><div class="preview" data-testid="next"></div></div>
45	    <div class="status" data-testid="status"></div>
46	    <button type="button" id="new-game">New game</button>
47	    <div class="help">
48	      <kbd>←</kbd> <kbd>→</kbd> move<br>
49	      <kbd>↑</kbd> rotate<br>
50	      <kbd>↓</kbd> soft drop<br>
51	      <kbd>Space</kbd> hard drop
52	    </div>
53	  </div>
54	</div>
55	<script>
56	(function () {
57	  'use strict';
58	
59	  var ROWS = 20, COLS = 10;
60	  var TYPES = ['I', 'O', 'T', 'S', 'Z', 'J', 'L'];
61	  var COLORS = {
62	    I: '#00bcd4', O: '#f5c400', T: '#9c27b0', S: '#43a047',
63	    Z: '#e53935', J: '#1e63d6', L: '#fb8c00'
64	  };
65	  // Spawn orientation, as [row, col] offsets from the piece origin.
66	  var SHAPES = {
67	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
68	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
69	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
70	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
71	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
72	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
73	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
74	  };
75	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
76	  var GRAVITY_MS = 1000;
77	
78	  // Clockwise rotation states. Each is a quarter turn of the one before, inside the
79	  // piece's box (2x2 for O, 3x3 for the rest). I is listed by hand so it turns about its middle.
80	  var ROTATIONS = {};
81	  TYPES.forEach(function (t) {
82	    var n = t === 'O' ? 2 : 3;
83	    var states = [SHAPES[t]];
84	    for (var k = 1; k < 4; k++) {
85	      states.push(states[k - 1].map(function (p) { return [p[1], n - 1 - p[0]]; }));
86	    }
87	    ROTATIONS[t] = states;
88	  });
89	  ROTATIONS.I = [
90	    SHAPES.I,
91	    [[0, 2], [1, 2], [2, 2], [3, 2]],
92	    [[1, 0], [1, 1], [1, 2], [1, 3]],
93	    [[0, 1], [1, 1], [2, 1], [3, 1]]
94	  ];
95	  // Sideways shifts tried, in order, when a rotated piece does not fit where it is.
96	  var KICKS = [0, -1, 1, -2, 2];
97	
98	  // Locking rule (a project decision): a gravity step that cannot move the piece down counts
99	  // one tick of lock delay; the piece locks on the LOCK_TICKS-th such tick. A successful left or
100	  // right move during the delay restarts it, at most MAX_RESTARTS times per piece. Hard drop
101	  // locks at once.
102	  var LOCK_TICKS = 2;
103	  var MAX_RESTARTS = 3;
104	
105	  // Game state. `board` holds the locked cells: a piece letter, or '' when empty.
106	  var board, current, queue, bag, score, level, lines, status, timer = null;
107	
108	  // ---- DOM ----
109	  var boardEl = document.querySelector('[data-testid="board"]');
110	  var scoreEl = document.querySelector('[data-testid="score"]');
111	  var levelEl = document.querySelector('[data-testid="level"]');
112	  var linesEl = document.querySelector('[data-testid="lines"]');
113	  var nextEl = document.querySelector('[data-testid="next"]');
114	  var statusEl = document.querySelector('[data-testid="status"]');
115	  var cellEls = [];
116	  var miniEls = [];
117	
118	  for (var r = 0; r < ROWS; r++) {
119	    cellEls.push([]);
120	    for (var c = 0; c < COLS; c++) {
121	      var el = document.createElement('div');
122	      el.className = 'cell';
123	      el.setAttribute('data-testid', 'cell');
124	      el.setAttribute('data-row', String(r));
125	      el.setAttribute('data-col', String(c));
126	      boardEl.appendChild(el);
127	      cellEls[r].push(el);
128	    }
129	  }
130	  for (var mr = 0; mr < 2; mr++) {
131	    miniEls.push([]);
132	    for (var mc = 0; mc < 4; mc++) {
133	      var m = document.createElement('div');
134	      m.className = 'mini';
135	      nextEl.appendChild(m);
136	      miniEls[mr].push(m);
137	    }
138	  }
139	
140	  function paint(el, type) {
141	    el.setAttribute('data-filled', type ? 'true' : 'false');
142	    el.setAttribute('data-piece', type || '');
143	    el.style.backgroundColor = type ? COLORS[type] : '';
144	  }
145	
146	  function render() {
147	    var view = board.map(function (row) { return row.slice(); });
148	    if (current) {
149	      pieceCells(current).forEach(function (p) { view[p[0]][p[1]] = current.type; });
150	    }
151	    for (var r = 0; r < ROWS; r++) {
152	      for (var c = 0; c < COLS; c++) paint(cellEls[r][c], view[r][c]);
153	    }
154	
155	    var upcoming = queue[0] || '';
156	    for (var mr = 0; mr < 2; mr++) {
157	      for (var mc = 0; mc < 4; mc++) paint(miniEls[mr][mc], '');
158	    }
159	    if (upcoming) {
160	      SHAPES[upcoming].forEach(function (p) { paint(miniEls[p[0]][p[1]], upcoming); });
161	    }
162	
163	    scoreEl.textContent = String(score);
164	    levelEl.textContent = String(level);
165	    linesEl.textContent = String(lines);
166	    statusEl.textContent = status === 'over' ? 'Game over' : '';
167	  }
168	
169	  // ---- Pieces ----
170	  function randomPiece() {
171	    if (!bag.length) {
172	      bag = TYPES.slice();
173	      for (var i = bag.length - 1; i > 0; i--) {
174	        var j = Math.floor(Math.random() * (i + 1));
175	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
176	      }
177	    }
178	    return bag.pop();
179	  }
180	
181	  function takeNext() {
182	    if (!queue.length) queue.push(randomPiece());
183	    var type = queue.shift();
184	    if (!queue.length) queue.push(randomPiece());
185	    return type;
186	  }
187	
188	  function pieceCells(piece) {
189	    return ROTATIONS[piece.type][piece.rot].map(function (p) { return [piece.row + p[0], piece.col + p[1]]; });
190	  }
191	
192	  function fits(cells) {
193	    return cells.every(function (p) {
194	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && !board[p[0]][p[1]];
195	    });
196	  }
197	
198	  function spawn() {
199	    var type = takeNext();
200	    var piece = { type: type, row: 0, col: SPAWN_COL[type], rot: 0, lockTicks: 0, restarts: 0 };
201	    if (!fits(pieceCells(piece))) {
202	      current = null;
203	      status = 'over';
204	      stopTimer();
205	      return;
206	    }
207	    current = piece;
208	  }
209	
210	  function move(dr, dc) {
211	    if (!current) return false;
212	    var moved = { type: current.type, row: current.row + dr, col: current.col + dc, rot: current.rot };
213	    if (!fits(pieceCells(moved))) return false;
214	    current.row = moved.row;
215	    current.col = moved.col;
216	    return true;
217	  }
218	
219	  // Left or right. During the lock delay, a successful move restarts it, up to the cap.
220	  function shift(dc) {
221	    if (!move(0, dc)) return;
222	    if (current.lockTicks > 0 && current.restarts < MAX_RESTARTS) {
223	      current.lockTicks = 0;
224	      current.restarts++;
225	    }
226	  }
227	
228	  // Try the next clockwise state in place, then shifted sideways. If nothing fits, change nothing.
229	  function rotateCW() {
230	    if (!current) return false;
231	    var rot = (current.rot + 1) % 4;
232	    for (var i = 0; i < KICKS.length; i++) {
233	      var turned = { type: current.type, row: current.row, col: current.col + KICKS[i], rot: rot };
234	      if (fits(pieceCells(turned))) {
235	        current.col = turned.col;
236	        current.rot = rot;
237	        return true;
238	      }
239	    }
240	    return false;
241	  }
242	
243	  function lock() {
244	    pieceCells(current).forEach(function (p) { board[p[0]][p[1]] = current.type; });
245	    current = null;
246	    spawn();
247	  }
248	
249	  // One gravity step. The real timer and tick() both run exactly this.
250	  function gravityStep() {
251	    if (status !== 'running' || !current) return;
252	    if (move(1, 0)) {
253	      current.lockTicks = 0;
254	      return;
255	    }
256	    current.lockTicks++;
257	    if (current.lockTicks >= LOCK_TICKS) lock();
258	  }
259	
260	  function gravity() {
261	    gravityStep();
262	    render();
263	  }
264	
265	  function stopTimer() {
266	    if (timer !== null) { clearInterval(timer); timer = null; }
267	  }
268	
269	  function startTimer() {
270	    stopTimer();
271	    timer = setInterval(gravity, GRAVITY_MS);
272	  }
273	
274	  // ---- Actions ----
275	  function input(action) {
276	    if (status !== 'running' || !current) return;
277	    if (action === 'left') shift(-1);
278	    else if (action === 'right') shift(1);
279	    else if (action === 'rotateCW') rotateCW();
280	    else if (action === 'softDrop') gravityStep();
281	    else if (action === 'hardDrop') {
282	      while (move(1, 0)) { /* fall to the lowest reachable row */ }
283	      lock();
284	    }
285	    render();
286	  }
287	
288	  function toQueue(list) {
289	    return (Array.isArray(list) ? list : [])
290	      .map(function (t) { return String(t).toUpperCase(); })
291	      .filter(function (t) { return SHAPES.hasOwnProperty(t); });
292	  }
293	
294	  function newGame(list) {
295	    board = [];
296	    for (var r = 0; r < ROWS; r++) board.push(new Array(COLS).fill(''));
297	    bag = [];
298	    queue = toQueue(list);
299	    score = 0;
300	    level = 1;
301	    lines = 0;
302	    status = 'running';
303	    current = null;
304	    spawn();
305	    if (status === 'running') startTimer();
306	    render();
307	  }
308	
309	  function setQueue(list) {
310	    queue = toQueue(list);
311	    render();
312	  }
313	
314	  function setBoard(rows) {
315	    for (var r = 0; r < ROWS; r++) {
316	      var line = rows && typeof rows[r] === 'string' ? rows[r] : '';
317	      for (var c = 0; c < COLS; c++) {
318	        var ch = line.charAt(c).toUpperCase();
319	        board[r][c] = SHAPES.hasOwnProperty(ch) ? ch : '';
320	      }
321	    }
322	    render();
323	  }
324	
325	  function getBoard() {
326	    return board.map(function (row) {
327	      return row.map(function (t) { return t || '.'; }).join('');
328	    });
329	  }
330	
331	  function getState() {
332	    return {
333	      current: current ? { type: current.type, cells: pieceCells(current) } : null,
334	      next: queue.slice(),
335	      score: score,
336	      level: level,
337	      lines: lines,
338	      status: status
339	    };
340	  }
341	
342	  function tick(n) {
343	    var steps = n === undefined ? 1 : n;
344	    for (var i = 0; i < steps; i++) gravity();
345	  }
346	
347	  window.__tetris = {
348	    newGame: newGame,
349	    setQueue: setQueue,
350	    setBoard: setBoard,
351	    tick: tick,
352	    input: input,
353	    getBoard: getBoard,
354	    getState: getState
355	  };
356	
357	  var KEYS = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'rotateCW', ArrowDown: 'softDrop', ' ': 'hardDrop', Spacebar: 'hardDrop' };
358	  document.addEventListener('keydown', function (e) {
359	    var action = KEYS[e.key];
360	    if (!action) return;
361	    e.preventDefault();
362	    input(action);
363	  });
364	  document.getElementById('new-game').addEventListener('click', function (e) {
365	    e.currentTarget.blur();
366	    newGame();
367	  });
368	
369	  newGame();
370	})();
371	</script>
372	</body>
373	</html>
